 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the solid separator and extract its two equal-sized panels.
    panels = None
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and h-r-1 == r:
            panels = (grid[:r], grid[r+1:])
            break
    if panels is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c > 0 and w-c-1 == c:
                panels = ([row[:c] for row in grid], [row[c+1:] for row in grid])
                break
    if panels is None:
        return [row[:] for row in grid]
    a, b = panels
    ca = {x for row in a for x in row}
    cb = {x for row in b for x in row}
    shared = ca & cb
    if len(shared) != 1:
        return [row[:] for row in grid]
    color = next(iter(shared))
    # A single marked pixel in an otherwise blank (zero) panel signals a solid fill.
    for p in (a, b):
        flat = [x for row in p for x in row]
        if 0 in flat and sum(x != 0 for x in flat) == 1 and color != 0:
            return [[color for _ in row] for row in p]
    # Matching shared-color pixels become 3; all other cells retain the shared color.
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(len(a[0]))] for r in range(len(a))]
